const conf = $('Configuración').first().json;
const lista = (x) => (Array.isArray(x) ? x : x ? [x] : []);
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const escapar = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Each name matches at the start of a word and without accents: "quimica" finds "Química".
const convenios = lista(conf.convenios)
  .filter(Boolean)
  .map((c) => ({ nombre: c, patron: new RegExp('\\b' + escapar(norm(c))) }));
const encuentra = (titulo) => convenios.find((x) => x.patron.test(norm(titulo)));
const salida = [];

// BOE: state-wide agreements. On Sundays and holidays there is no summary.
const boe = $('Sumario del BOE').first().json;
const sumario = boe.data && typeof boe.data === 'object' ? boe.data.sumario : null;
if (sumario) {
  for (const diario of lista(sumario.diario)) {
    for (const sec of lista(diario.seccion)) {
      if (String(sec.codigo) !== '3') continue;
      for (const dep of lista(sec.departamento)) {
        for (const ep of lista(dep.epigrafe)) {
          // Labour agreements only: the plain "Convenios" epigraph is agreements between administrations.
          if (!norm(ep.nombre).startsWith('convenios colectivos')) continue;
          for (const it of lista(ep.item)) {
            const c = encuentra(it.titulo);
            if (!c) continue;
            salida.push({
              json: {
                boletin: 'BOE',
                fecha: sumario.metadatos.fecha_publicacion,
                convenio: c.nombre,
                titulo: it.titulo,
                identificador: it.identificador,
                url_html: it.url_html,
                url_pdf: typeof it.url_pdf === 'object' ? it.url_pdf.texto : it.url_pdf,
              },
            });
          }
        }
      }
    }
  }
}

// BOCM: Madrid agreements. Its feed only carries the latest bulletin, so it counts only when that bulletin is the day being checked.
if (conf.bocm !== false) {
  const dia = conf.fecha || $now.setZone('Europe/Madrid').toFormat('yyyyMMdd');
  const rss = String($input.first().json.data || '');
  const entidades = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&amp;/g, '&');
  for (const item of rss.match(/<item>[\s\S]*?<\/item>/g) || []) {
    const link = ((item.match(/<link>([^<]+)<\/link>/) || [])[1] || '').trim();
    const m = link.match(/bocm-(\d{8})-(\d+)$/);
    if (!m || m[1] !== dia) continue;
    // The description is "<p>Subject<br />– Title</p>" followed by a fixed footer.
    const desc = entidades((item.match(/<description>([\s\S]*?)<\/description>/) || [])[1] || '');
    const texto = desc.split(/\n\s*\n/)[0].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (!/\bconvenios? colectivos?\b/.test(norm(texto))) continue;
    const titulo = texto.includes('–') ? texto.slice(texto.indexOf('–') + 1).trim() : texto;
    const c = encuentra(titulo);
    if (!c) continue;
    const [a, ms, d] = [m[1].slice(0, 4), m[1].slice(4, 6), m[1].slice(6, 8)];
    salida.push({
      json: {
        boletin: 'BOCM',
        fecha: m[1],
        convenio: c.nombre,
        titulo,
        identificador: `BOCM-${m[1]}-${m[2]}`,
        url_html: link,
        url_pdf: `https://www.bocm.es/boletin/CM_Orden_BOCM/${a}/${ms}/${d}/BOCM-${m[1]}-${m[2]}.PDF`,
      },
    });
  }
}
// No news in either bulletin: the flow stops here and sends nothing.
return salida;

const conf = $('Configuración').first().json;
const items = $input.all().map((i) => i.json);
const f = items[0].fecha;
const fecha = `${f.slice(6, 8)}/${f.slice(4, 6)}/${f.slice(0, 4)}`;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const mayus = (s) => s.charAt(0).toUpperCase() + s.slice(1);

// What was published, from the title. A title can name several things: "Acuerdo de prórroga y aprobación de las tablas salariales".
// "tablas de retribuciones" and "tablas económicas" are salary tables too.
const tipos = [
  [/\bsentencia\b/, 'sentencia'],
  [/\blaudo\b/, 'laudo arbitral'],
  [/\btablas\b/, 'tablas salariales'],
  [/\brevision salarial\b|\bincrementos? salarial(es)?\b|\bactualizacion salarial\b/, 'revisión salarial'],
  [/\bprorroga\b/, 'prórroga'],
  [/\bacta de la comision paritaria\b/, 'acta de la comisión paritaria'],
  [/\bmodificacion\b/, 'modificación'],
];
// The title opens with the resolution's own date and office; what is published comes after
// "registra y publica" in the BOE and after "registro, depósito y publicación" in the BOCM.
const objeto = (titulo) => {
  const m =
    titulo.match(/registra y publica (?:el |la |los |las )?(.*)$/i) ||
    titulo.match(/registro, dep[oó]sito y publicaci[oó]n (?:del |de la |de los |de las |de )?(.*)$/i);
  const t = (m ? m[1] : titulo).replace(/,\s*suscrit[oa]s? .*$/i, '').replace(/\s*\(C[oó]digo n[uú]mero[^)]*\)/i, '').trim();
  return mayus(t.replace(/\.*$/, '.'));
};
// Only a whole agreement is "new"; anything else unrecognised is just "novedad".
// A correction says so in the part of the title that objeto() leaves out.
const tipo = (titulo) => {
  const o = norm(objeto(titulo));
  const t = tipos.filter(([re]) => re.test(o)).map(([, n]) => n);
  const base = t.length ? t.join(' y ') : /^([ivxlc]+ )?convenio colectivo\b/.test(o) ? 'convenio nuevo' : 'novedad';
  return mayus(/\bcorrigen errores\b|\bcorreccion de errores\b/.test(norm(titulo)) ? `corrección de errores en ${base}` : base);
};
const periodo = (titulo) => {
  const anos = (objeto(titulo).match(/\b20\d\d\b/g) || []).map(Number);
  if (!anos.length) return '';
  const [a, b] = [Math.min(...anos), Math.max(...anos)];
  return a === b ? ` ${a}` : ` ${a}–${b}`;
};

const asunto = `${fecha}: ${items.length === 1 ? 'novedad en uno de tus convenios' : `${items.length} novedades en tus convenios`}`;
const bloque = (d) =>
  `<b>${esc(mayus(d.convenio))}</b> (${d.boletin}): ${esc(tipo(d.titulo) + periodo(d.titulo))}\n${esc(objeto(d.titulo))}\n` +
  `<a href="${esc(d.url_html)}">Ver en el ${d.boletin}</a>` + (d.url_pdf ? ` | <a href="${esc(d.url_pdf)}">PDF</a>` : '');
// Telegram caps a message at 4096 characters.
let telegram = `<b>${esc(asunto)}</b>`;
let n = 0;
while (n < items.length && (telegram + '\n\n' + bloque(items[n])).length <= 3800) telegram += '\n\n' + bloque(items[n++]);
if (n < items.length) telegram += `\n\n…y ${items.length - n} más.`;

const texto = items
  .map((d) => `- ${mayus(d.convenio)} (${d.boletin}): ${tipo(d.titulo)}${periodo(d.titulo)}\n  ${objeto(d.titulo)}\n  ${d.url_html}`)
  .join('\n');
const chats = (Array.isArray(conf.chats_telegram) ? conf.chats_telegram : [conf.chats_telegram]).filter(Boolean);
if (!chats.length) throw new Error('No hay ningún chat en chats_telegram: pon tu ID de Telegram en Configuración.');
return chats.map((chat) => ({ json: { chat: String(chat), asunto, total: items.length, texto, telegram } }));
